mapper.select:
SELECT T0.BOOKSET_ID AS FINPRODID, T0.BOOKSET_NAME AS FINPRODNAME, T0.ACCT_MODE AS FINPRODTYPE, t2.val_date AS VALDATE, IFNULL(T2.BUILD_STATUS, '0') AS BUILDSTATUS, '' AS ERRORINFO, T2.ERROR_TYPE AS ERRORTYPE from BOK_BOOKSET T0 inner JOIN BOK_VALBAL_TABLE_LOG T2 ON T0.ACCT_SUBJECT_ID = T2.FINPROD_ID AND T2.VAL_BAL_FLAG = #{fileType} where 1 = 1
AND T0.BOOKSET_ID in
#{prdId}
AND T0.ACCT_MODE in
#{prodType}
and t2.val_date >= #{valDateBegin,jdbcType=DATE}
and t2.val_date <= #{valDateEnd,jdbcType=DATE}
AND IFNULL(T2.BUILD_STATUS, '0') in
#{buildStatus}
order by t2.VAL_DATE desc

select prd.finprod_id,IFNULL(prd.finprod_abbr,prd.finprod_name) finprod_abbr from fin_product prd
	where 1=1

	AND prd.FINPROD_TYPE = #{finprodType}

SELECT B.VAL_DATE AS valDate,B.FINPROD_ID AS finprodId,B.FINPROD_NAME AS finprodName, SUM(B.CAPITAL） AS CAPITAL,SUM(B.ASSET_VALUE) AS assetValue,SUM(B.NET_UNIT_VALUE） AS netUnitValue, /**add by leipeng UAT-230 单位净值、累计净值、七日年化收益率、应付利润，值不应该一直为0 20180903*/ SUM(B.TAOTALNETVALUE) AS totalNetValue,SUM(B.SEVENDAYRATE) AS sevenDayRate,SUM(B.PAYPROFIT) AS payProfit FROM ( SELECT A.VAL_DATE AS VAL_DATE,A.FINPROD_ID AS FINPROD_ID,A.FINPROD_NAME AS FINPROD_NAME, CASE WHEN A.DETAIL_DIST = '01' AND SUBJECT_NO = '22320101' THEN (CASE A.BAL_FLAG WHEN 'C'THEN 1 ELSE -1 END )*A.COST ELSE 0 END AS PAYPROFIT, CASE WHEN A.DETAIL_DIST = '02' THEN A.COST ELSE 0 END AS CAPITAL, CASE A.PROFIT_TYPE WHEN '01' THEN (CASE A.DETAIL_DIST WHEN '07' THEN A.MARKET_VALUE ELSE 0 END) WHEN '03' THEN (CASE A.DETAIL_DIST WHEN '28' THEN CAST(A.SUBJECT_NAME AS SIGNED INTEGER ) ELSE 0 END) ELSE 0 END ASSET_VALUE, /**add by leipeng UAT-230 单位净值、累计净值、七日年化收益率、应付利润，值不应该一直为0 20180903*/ CASE A.PROFIT_TYPE WHEN '01' THEN (CASE A.DETAIL_DIST WHEN '08' THEN CAST(A.SUBJECT_NAME AS SIGNED INTEGER ) ELSE 0 END ) WHEN '03' THEN (CASE A.DETAIL_DIST WHEN '29' THEN CAST(A.SUBJECT_NAME AS SIGNED INTEGER ) ELSE 0 END ) ELSE 0 END NET_UNIT_VALUE, CASE WHEN A.DETAIL_DIST = '17' THEN CAST(A.SUBJECT_NAME AS SIGNED INTEGER) ELSE 0 END AS TAOTALNETVALUE, CASE WHEN A.DETAIL_DIST = '33' THEN CAST(A.SUBJECT_NAME AS SIGNED INTEGER) ELSE 0 END AS SEVENDAYRATE FROM ( SELECT BVD.VAL_DATE AS VAL_DATE,BVD.COST AS COST,BVD.DETAIL_DIST AS DETAIL_DIST,BVD.SUBJECT_NO,BVD.SUBJECT_NAME, FP.FINPROD_ID AS FINPROD_ID,FP.FINPROD_NAME AS FINPROD_NAME ,FP.PROFIT_TYPE,BVD.BAL_FLAG,BVD.MARKET_VALUE AS MARKET_VALUE
FROM BOK_VAL_TABLE_DATA BVD JOIN BOK_BOOKSET BB ON BVD.BOOKSET_ID = BB.BOOKSET_ID JOIN FIN_PRODUCT FP ON BB.ACCT_SUBJECT_ID = FP.FINPROD_ID WHERE 1=1
AND BVD.VAL_DATE >= #{valDateBegin,jdbcType=DATE}
AND BVD.VAL_DATE <= #{valDateEnd,jdbcType=DATE}
AND BB.ACCT_SUBJECT_ID = #{prodId}
AND BVD.DETAIL_DIST IN ('01','02','07','08','17','28','29','33') ) A ) B GROUP BY B.VAL_DATE,B.FINPROD_ID,B.FINPROD_NAME

SELECT COUNT(*) FROM ( SELECT B.VAL_DATE AS valDate,B.FINPROD_ID AS finprodId,B.FINPROD_NAME AS finprodName, SUM(B.CAPITAL） AS CAPITAL,SUM(B.ASSET_VALUE) AS assetValue,SUM(B.NET_UNIT_VALUE） AS netUnitValue, /**add by leipeng UAT-230 单位净值、累计净值、七日年化收益率、应付利润，值不应该一直为0 20180903*/ SUM(B.TAOTALNETVALUE) AS TAOTALNETVALUE,SUM(B.SEVENDAYRATE) AS SEVENDAYRATE,SUM(B.PAYPROFIT) AS PAYPROFIT FROM ( SELECT A.VAL_DATE AS VAL_DATE,A.FINPROD_ID AS FINPROD_ID,A.FINPROD_NAME AS FINPROD_NAME, CASE WHEN A.DETAIL_DIST = '01' AND SUBJECT_NO = '22320101' THEN (CASE A.BAL_FLAG WHEN 'C' THEN 1 ELSE -1 END )*A.COST ELSE 0 END AS PAYPROFIT, CASE WHEN A.DETAIL_DIST = '02' THEN A.COST ELSE 0 END AS CAPITAL, CASE A.PROFIT_TYPE WHEN '01' THEN (CASE A.DETAIL_DIST WHEN '07' THEN A.COST ELSE 0 END) WHEN '03' THEN (CASE A.DETAIL_DIST WHEN '28' THEN CAST(A.SUBJECT_NAME AS SIGNED INTEGER ) ELSE 0 END) ELSE 0 END ASSET_VALUE, /**add by leipeng UAT-230 单位净值、累计净值、七日年化收益率、应付利润，值不应该一直为0 20180903*/ CASE A.PROFIT_TYPE WHEN '01' THEN (CASE A.DETAIL_DIST WHEN '08' THEN CAST(A.SUBJECT_NAME AS SIGNED INTEGER) ELSE 0 END) WHEN '03' THEN (CASE A.DETAIL_DIST WHEN '29' THEN CAST(A.SUBJECT_NAME AS SIGNED INTEGER) ELSE 0 END) ELSE 0 END NET_UNIT_VALUE, CASE WHEN A.DETAIL_DIST = '17' THEN CAST(A.SUBJECT_NAME AS SIGNED INTEGER) ELSE 0 END AS TAOTALNETVALUE, CASE WHEN A.DETAIL_DIST = '33' THEN CAST(A.SUBJECT_NAME AS SIGNED INTEGER) ELSE 0 END AS SEVENDAYRATE FROM ( SELECT BVD.VAL_DATE AS VAL_DATE,BVD.COST AS COST,BVD.DETAIL_DIST AS DETAIL_DIST,BVD.SUBJECT_NO,BVD.SUBJECT_NAME, FP.FINPROD_ID AS FINPROD_ID,FP.FINPROD_NAME AS FINPROD_NAME ,FP.PROFIT_TYPE,BVD.BAL_FLAG FROM BOK_VAL_TABLE_DATA BVD JOIN BOK_BOOKSET BB ON BVD.BOOKSET_ID = BB.BOOKSET_ID JOIN FIN_PRODUCT FP ON BB.ACCT_SUBJECT_ID = FP.FINPROD_ID WHERE 1=1
AND BVD.VAL_DATE >= #{valDateBegin,jdbcType=DATE}
AND BVD.VAL_DATE <= #{valDateEnd,jdbcType=DATE}
AND BB.ACCT_SUBJECT_ID = #{prodId}
AND BVD.DETAIL_DIST IN ('01','02','07','08','17','28','29','33') ) A ) B GROUP BY B.VAL_DATE,B.FINPROD_ID,B.FINPROD_NAME ) de
